            for (const line of lines) {
                if (line.startsWith('year:')) {
                    calendarData.year = parseInt(line.split(':')[1].trim());
                } else if (line.startsWith('month:')) {
                    calendarData.month = parseInt(line.split(':')[1].trim());
                } else if (line.startsWith('current_day:')) {
                    calendarData.current_day = parseInt(line.split(':')[1].trim());
